/// <summary>Safe overloads of every C function: spans instead of pointer + length, ref/in/out
/// instead of struct and scalar pointers, nint for handles. An empty span passes NULL; a
/// NUL-terminated string argument must contain a NUL byte. Pass
/// <c>in Unsafe.NullRef&lt;T&gt;()</c> for an optional struct argument to pass NULL.</summary>
internal static unsafe class Native
{
    internal static uint siaara_abi_version()
    {
        return Raw.siaara_abi_version();
