    {
        @out = 0;
        fixed (byte* p_utf8_path = utf8_path)
        fixed (siaara_read_options* p_options = &options)
        fixed (nint* p_out = &@out)
            return Raw.siaara_file_open((byte*)p_utf8_path, (nuint)utf8_path.Length, p_options, p_out);
    }

    internal static int siaara_file_open_memory(ReadOnlySpan<byte> data, in siaara_read_options options, out nint @out)
