    internal static int siaara_view_set_plane(nint view, ReadOnlySpan<double> point, ReadOnlySpan<double> normal, ReadOnlySpan<double> up, double pixel_spacing)
    {
        if (point.Length < 3) throw new ArgumentException("point needs 3 elements", nameof(point));
        if (normal.Length < 3) throw new ArgumentException("normal needs 3 elements", nameof(normal));
        if (up.Length < 3) throw new ArgumentException("up needs 3 elements", nameof(up));
        fixed (double* p_point = point)
        fixed (double* p_normal = normal)
        fixed (double* p_up = up)
            return Raw.siaara_view_set_plane(view, (double*)p_point, (double*)p_normal, (double*)p_up, pixel_spacing);
    }

